using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckMinefield.Editor {
public static class MinefieldGoddessAuthoring {
 public static void Upgrade(){var scene=EditorSceneManager.OpenScene(MinefieldAuthoring.Scene);Install(Object.FindAnyObjectByType<MinefieldMatch>());EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
 public static void Install(MinefieldMatch m){Flags(m);var catalog=SportsWeatherPresetsAuthoring.EnsureCatalog();m.weatherField.presets=catalog;m.weatherField.reduceSnowRandom=true;var cameras=m.views.views.Select(v=>v.view).Concat(new[]{m.views.broadcast.view}).ToArray();SportsWeatherRenderingAuthoring.Install(m.gameObject,cameras,MinefieldAuthoring.Folder);SportsScenicGradeAuthoring.Install(m.gameObject,cameras,MinefieldAuthoring.Folder,-.4f);SportsWeatherPickerAuthoring.Install(m,catalog,new Vector2(0,336));m.menus.pages[0].transform.Find("Title").GetComponent<RectTransform>().anchoredPosition=new Vector2(0,430);foreach(var text in m.menus.pages[0].GetComponentsInChildren<TMP_Text>(true))if(text.name=="Weather selection explanation")text.gameObject.SetActive(false);EditorUtility.SetDirty(m.weatherField);}
 public static void Flags(MinefieldMatch m){var theme=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme");string path="Assets/TruckMinefield/Materials/Depth tested outlined flag lettering.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material==null){material=new Material(theme.bodyFont.material);material.SetFloat("_OutlineWidth",.22f);material.SetColor("_OutlineColor",new Color(.015f,.025f,.04f));material.EnableKeyword("OUTLINE_ON");if(material.HasProperty("_ZTestMode"))material.SetFloat("_ZTestMode",4);AssetDatabase.CreateAsset(material,path);}
  foreach(var flag in m.blastFlags.Concat(m.landingFlags).Concat(m.bestFlags)){if(flag.backing!=null){Object.DestroyImmediate(flag.backing.gameObject);flag.backing=null;}if(flag.caption!=null)flag.caption.gameObject.SetActive(false);if(flag.attachedName==null){var label=new GameObject("Outlined identity attached to flag cloth").AddComponent<TextMeshPro>();flag.attachedName=label;label.transform.SetParent(flag.transform,false);label.font=theme.bodyFont;label.fontSharedMaterial=material;label.fontSize=5.5f;label.enableAutoSizing=true;label.fontSizeMin=3.5f;label.fontSizeMax=5.5f;label.alignment=TextAlignmentOptions.Center;label.rectTransform.sizeDelta=new Vector2(6,3);label.isOverlay=false;var billboard=label.gameObject.AddComponent<SportsPerCameraBillboard>();billboard.distanceSizing=true;billboard.referenceDistance=50;billboard.maximumPixelHeight=35;billboard.maximumPixelWidth=165;billboard.maximumLabelDistance=600;label.transform.position=flag.cloth.bounds.center+Vector3.up*.25f;label.GetComponent<Renderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;}
   var name=flag.attachedName;name.rectTransform.sizeDelta=new Vector2(20,4);name.fontSizeMin=12;name.fontSizeMax=24;name.enableWordWrapping=false;name.extraPadding=true;
   var facing=name.GetComponent<SportsPerCameraBillboard>();facing.cameraFacingOffset=flag.cloth.bounds.extents.magnitude+.25f;facing.maximumPixelHeight=30;facing.maximumPixelWidth=210;
   material.SetFloat("_OutlineWidth",.32f);material.SetColor("_OutlineColor",new Color(.005f,.008f,.012f,1));material.SetColor("_UnderlayColor",new Color(0,0,0,.95f));material.SetFloat("_UnderlayOffsetX",.65f);material.SetFloat("_UnderlayOffsetY",-.65f);material.SetFloat("_UnderlayDilate",.2f);material.SetFloat("_UnderlaySoftness",.12f);material.EnableKeyword("UNDERLAY_ON");name.UpdateMeshPadding();EditorUtility.SetDirty(name);EditorUtility.SetDirty(facing);EditorUtility.SetDirty(material);
   EditorUtility.SetDirty(flag);}
 }
}
}
